struct MascotSandbox: View {
    var body: some View {
        ScrollView {
            VStack(spacing: 24) {
                GeometryReader { geo in
                    let s = geo.size.width / MascotSheet.size.width
                    MascotSheet()
                        .scaleEffect(s, anchor: .topLeading)
                }
                .aspectRatio(MascotSheet.size, contentMode: .fit)

                MascotPlayground()
            }
            .padding(16)
        }
        .background(MascotPalette.background)
    }
}

struct MascotPlayground: View {
    @State private var poseIndex: Double = 1
    @State private var expressionIndex: Double = 2
    @State private var size: Double = 260

    var body: some View {
        let pose = ApplePose.allCases[Int(poseIndex)]
        let expression = AppleFace.Expression.allCases[Int(expressionIndex)]

        VStack(spacing: 16) {
            AppleMascotView(expression: expression, pose: pose)
                .frame(width: size, height: size)
                .id("\(pose.rawValue)-\(expression.rawValue)")
                .transition(.opacity)
                .animation(.easeInOut(duration: 0.2), value: poseIndex)
                .animation(.easeInOut(duration: 0.2), value: expressionIndex)
                .frame(height: 320)

            slider("Pose · \(pose.title)", value: $poseIndex, range: 0...Double(ApplePose.allCases.count - 1))
            slider("Expression · \(expression.title)", value: $expressionIndex, range: 0...Double(AppleFace.Expression.allCases.count - 1))
            slider("Size · \(Int(size))", value: $size, range: 80...320)

            MascotFlow(spacing: 12) {
                ForEach(AppleFace.Expression.allCases) { e in
                    AppleFace(expression: e).frame(width: 40, height: 32)
                }
            }
        }
        .padding(16)
        .background(RoundedRectangle(cornerRadius: 16).fill(.white))
    }

    private func slider(_ label: String, value: Binding<Double>, range: ClosedRange<Double>) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(label)
                .font(.system(size: 13, weight: .semibold))
                .foregroundStyle(MascotPalette.details)
            Slider(value: value, in: range, step: 1)
                .tint(MascotPalette.appleRed)
        }
    }
}

